def tool_execution_node(state):
    tool_call = state["messages"][-1].tool_calls[0]
    name, args = tool_call["name"], tool_call["args"]

    # The node doesn't care whether this tool is local or MCP-provided --
    # the orchestration layer routes it to the right place either way.
    if name in mcp_tool_registry:
        client = mcp_tool_registry[name]["client"]
        result = client.call_tool(name, args)     # MCP hop
    else:
        result = local_tools[name](**args)         # direct call

    return {"messages": [ToolMessage(content=result, tool_call_id=tool_call["id"])]}
