def aggregate_tools(mcp_clients: dict) -> list:
    tools = []
    for server_name, client in mcp_clients.items():
        try:
            for t in client.list_tools():
                t["name"] = f"{server_name}.{t['name']}"   # namespace to avoid collisions
                tools.append(t)
        except ConnectionError:
            # partial connectivity: degrade gracefully, don't fail everything
            log.warning(f"{server_name} unreachable, continuing without its tools")
            continue
    return tools
